/**
 * Sanctions screening of wallet addresses, the same everywhere: the hosted and
 * the self-hosted executor (apps/executor/src/service.ts) refuse a listed
 * follower or leader on every request that lets a wallet trade or be copied,
 * and hold what already runs; the API (apps/server/src/builder/sanctions.ts, a
 * copy below the marker) signs no fee terms for one; the browser
 * (apps/web/src/legal/screening.ts) signs nothing for one and asks the
 * Chainalysis oracle about every other address as well.
 *
 * THE LIST (sanctionsList.ts) is a file in the repository, generated by
 * scripts/update-sanctions-list.mjs from the source the browser asks: the
 * Chainalysis sanctions oracle on Ethereum mainnet, its mirror of the crypto
 * addresses on OFAC's SDN list. Nothing is fetched at start-up or while
 * running, so a screen never depends on a third party being up: an address is
 * listed or it is not. Refreshing it is running the script, committing both
 * copies and releasing.
 */
import { SANCTIONED_ADDRESSES, SANCTIONS_LIST_META } from './sanctionsList.ts';
import type { RegionPolicy } from './policy.ts';

export { SANCTIONS_LIST_META };

/**
 * `policy`, unless one of `addresses` (the follower, the leader) is listed:
 * then a refusal - the runtimes hold a copy or an algo whose policy does not
 * allow it, as for a blocked country.
 */
export function screenPolicy(policy: RegionPolicy, ...addresses: Array<string | null | undefined>): RegionPolicy {
  const hit = sanctionedOf(addresses);
  if (hit === null) return policy;
  return { ...policy, region: 'blocked', allowed: false, closeOnly: false, maxLeverage: null, reason: hit === 0 ? SANCTIONED_WALLET_REASON : SANCTIONED_LEADER_REASON };
}

// ---- shared with apps/server/src/builder/sanctions.ts below this line ----

const LISTED: ReadonlySet<string> = new Set(SANCTIONED_ADDRESSES.map((a) => a.toLowerCase()));
/** Tests only: addresses listed on top (a test cannot sign for a listed wallet). Never fewer than the list. */
const EXTRA = new Set<string>();

/** Whether `address` (any case, 0x and 40 hex) is on the sanctions list. Anything that is not an address: false. */
export function isSanctionedAddress(address: unknown): boolean {
  if (typeof address !== 'string') return false;
  const a = address.trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(a) && (LISTED.has(a) || EXTRA.has(a));
}

/** For tests: treat these addresses as listed too (until _resetSanctionsForTests). */
export function _sanctionForTests(...addresses: string[]): void {
  for (const a of addresses) EXTRA.add(a.toLowerCase());
}

/** For tests: only the list again. */
export function _resetSanctionsForTests(): void {
  EXTRA.clear();
}

/** The position in `addresses` of the first listed one, or null. */
export function sanctionedOf(addresses: ReadonlyArray<string | null | undefined>): number | null {
  const i = addresses.findIndex((a) => isSanctionedAddress(a));
  return i < 0 ? null : i;
}

/** The reason shown for a listed wallet. */
export const SANCTIONED_WALLET_REASON =
  'This wallet address is on a sanctions list, so ValueDesk cannot be used with it. If you believe this is a mistake, contact us at the address in the Impressum.';

/** The reason shown for a copy of a listed trader. */
export const SANCTIONED_LEADER_REASON =
  'This trader\'s wallet address is on a sanctions list, so it cannot be copied through ValueDesk.';
